// classic.js (script tag, no type=module)
var legacy = 'global'; // becomes window.legacy

// app.mjs (module)
var modern = 'module-scoped'; // NOT on globalThis
console.log(globalThis.modern); // undefined

console.log(getVersion());

import { getVersion } from './version.mjs';

// Works — imports are hoisted and evaluated before module body
// C#: using only aliases names; import executes the module

// cjs.cjs
const { readFileSync } = require('node:fs');
module.exports = { readFileSync };

// esm.mjs
import { readFileSync } from 'node:fs';
export { readFileSync };

// package.json "type":"module" makes .js files ESM by default
